INSERT INTO "SitePage" ("key", "published", "updatedByName", "updatedAt") VALUES ('home', '{"hero":{"eyebrow":"IELTS | Study Abroad","headline":"Invest in dreams build your career with","text":"From IELTS preparation to university admission and visa success — GlobalEd guides Bangladeshi students to 13 study destinations with free, honest counselling.","image":{"src":"/images/hero/home-hero.jpg","alt":"Students sitting an English language test in an exam hall with headphones"},"shown":true},"stats":{"shown":true},"services":{"eyebrow":"Our Services","title":"End-to-End Study Abroad Support","description":"From your first counselling session to your first day on campus — we''ve got every step covered.","shown":true},"howItWorks":{"eyebrow":"How It Works","title":"Your Step-by-Step Study Abroad Process","description":"A clear, proven path from your first meeting with us to your first day abroad. Scroll to follow the journey.","steps":[{"title":"Free Counselling","description":"Share your goals — we assess your profile and explore your options together.","icon":"MessageCircle"},{"title":"Destination & University","description":"Shortlist the right country, course, and university for your budget and ambitions.","icon":"MapPin"},{"title":"Application & Offer","description":"We prepare and submit flawless applications, then follow up until your offer arrives.","icon":"FileCheck"},{"title":"Documentation","description":"Every document double-checked against the exact embassy checklist.","icon":"ClipboardCheck"},{"title":"Visa Application","description":"Mock interviews and precise filing — the reason behind our strong visa success rate.","icon":"Stamp"},{"title":"Pre-Departure & Beyond","description":"Briefings, accommodation, airport pickup, and support after you land.","icon":"PlaneTakeoff"}],"shown":true},"destinations":{"eyebrow":"Study Destinations","title":"Best Study Abroad Destinations from Bangladesh","description":"Thirteen countries, hundreds of partner universities, one counsellor guiding you to the right choice.","shown":true},"whyUs":{"eyebrow":"Why GlobalEd","title":"Your Trusted Partner for Studying Abroad","description":"500+ students placed over 7+ years — here''s why families across Bangladesh choose GlobalEd.","reasons":[{"title":"Proven Visa Success","description":"A 90% visa success rate built on honest guidance and airtight documentation.","icon":"ShieldCheck"},{"title":"Certified Counsellors","description":"Certified counsellors, experienced IELTS instructors, and visa documentation experts guide every step.","icon":"Users"},{"title":"Global Partner Network","description":"10+ partner universities across thirteen countries, matched to your goals and budget.","icon":"Globe2"},{"title":"Support Beyond the Visa","description":"From application to arrival, we stay with you through pre-departure briefings and settling in abroad.","icon":"HeartHandshake"}],"shown":true},"reviews":{"eyebrow":"Success Stories & Reviews","title":"Loved by Our Students","description":"Real reviews from students now studying at universities across the globe.","shown":true},"blogs":{"eyebrow":"Blogs & News","title":"Popular Blogs & News","description":"Practical guides on destinations, scholarships, IELTS, and English — written by our counsellors.","shown":true},"events":{"eyebrow":"Events","title":"Upcoming Events","description":"Meet university representatives, join free IELTS mock tests, and get on-spot assessments.","shown":true},"partners":{"title":"Our Partner Universities Worldwide","shown":true},"faqCta":{"shown":true},"seo":{"title":"GlobalEd | IELTS & Study Abroad Consultancy","description":"GlobalEd is a trusted study abroad and IELTS preparation consultancy in Bangladesh, guiding students to top destinations including the UK, USA, Canada, Australia, and Europe.","ogImage":"","ogImageAlt":""}}'::jsonb, 'Initial content', CURRENT_TIMESTAMP) ON CONFLICT ("key") DO NOTHING;
INSERT INTO "SitePage" ("key", "published", "updatedByName", "updatedAt") VALUES ('about', '{"hero":{"title":"About GlobalEd","description":"From a single IELTS classroom to one of Bangladesh''s most trusted study abroad consultancies."},"cards":{"successTitle":"Our Success","successText":"Milestones since 2013, students placed, and real student success stories.","organizationTitle":"Our Organization","organizationText":"Our story, mission, vision, and sister educational organizations.","teamTitle":"Our Team","teamText":"Board of Directors and the people behind your success."},"seo":{"title":"About Us | GlobalEd","description":"Learn about GlobalEd — our history since 2013, our mission and vision, our sister educational organizations, board of directors, and the team behind thousands of study abroad successes.","ogImage":"","ogImageAlt":""}}'::jsonb, 'Initial content', CURRENT_TIMESTAMP) ON CONFLICT ("key") DO NOTHING;
INSERT INTO "SitePage" ("key", "published", "updatedByName", "updatedAt") VALUES ('about-organization', '{"hero":{"title":"Our Organization","description":"From a single IELTS classroom to one of Bangladesh''s most trusted study abroad consultancies."},"story":{"eyebrow":"Our Organization","title":"Our Story","paragraphs":["GlobalEd is a sister concern of Global Citizen Limited, an organization officially authorized by the British Council. Global Citizen Limited has been playing a vital role in IELTS registration and testing, ensuring a smooth and reliable process in coordination with the British Council.","As a sub-brand of Global Citizen Limited, GlobalEd focuses on delivering a broader range of services, including online courses, skill-based training, career counseling, corporate workshops, and visa/admission guidance. With a vision to empower learners and professionals, GlobalEd is dedicated to building pathways toward global education, career growth, and international opportunities.","Global Citizen Limited and GlobalEd work together to prepare students and professionals for global opportunities. Global Citizen Limited is an authorized partner of the British Council, providing official IELTS registration and testing services. Through GlobalEd, we offer online courses and certification programs, career counseling, visa and admission support, as well as corporate training and workshops, enabling students and professionals to gain international-level knowledge and skills."]},"journey":{"title":"Our Journey","milestones":[{"year":"2013","milestone":"Founded as an IELTS coaching centre in Dhanmondi"},{"year":"2016","milestone":"Launched full study abroad consultancy services"},{"year":"2019","milestone":"Opened Banani branch; crossed 1,000 student placements"},{"year":"2022","milestone":"Opened Chattogram branch; added Japanese language courses"},{"year":"2025","milestone":"Reached 5,000+ students placed across 13 destinations"}]},"missionVision":{"mission":"Preparing Bangladeshi students and professionals through world-class education, modern training, and expert guidance, so they can confidently pursue global opportunities, competitive careers, and international-level success.","vision":"To be Bangladesh''s most trusted education consultancy — measured not by the number of files we process, but by the number of dreams we deliver."},"sisters":{"eyebrow":"Our Family","title":"Our Sister Educational Organizations","organizations":[{"name":"Global Citizen Limited (GCL)","description":"Our parent organization — British Council authorized for IELTS registration and testing.","logo":{"src":"","alt":""}},{"name":"GlobalEd Language Club","description":"Our language training wing offering IELTS, Spoken English, and Japanese language programs.","logo":{"src":"/images/logos/sister-language-club.svg","alt":"GlobalEd Language Club logo"}},{"name":"GlobalEd Foundation","description":"A non-profit initiative providing free counselling and scholarship support to underprivileged students.","logo":{"src":"/images/logos/sister-foundation.svg","alt":"GlobalEd Foundation logo"}}]},"seo":{"title":"Our Organization | GlobalEd","description":"GlobalEd''s story, mission, vision, and our sister educational organizations under Global Citizen Limited.","ogImage":"","ogImageAlt":""}}'::jsonb, 'Initial content', CURRENT_TIMESTAMP) ON CONFLICT ("key") DO NOTHING;
INSERT INTO "SitePage" ("key", "published", "updatedByName", "updatedAt") VALUES ('about-success', '{"hero":{"title":"Our Success","description":"Since 2013, we''ve grown from a single IELTS classroom into a track record thousands of students trust."},"milestones":{"eyebrow":"Our Journey","title":"Milestones Along the Way"},"photos":{"photos":[{"photo":{"src":"/images/success/mou-signing.jpg","alt":"MOU signing ceremony between Sonargaon University and GlobalEd"}},{"photo":{"src":"/images/success/ribbon-confetti.jpg","alt":"Ribbon-cutting with confetti at a GlobalEd branch opening"}},{"photo":{"src":"/images/success/ribbon-opening.jpg","alt":"Ribbon-cutting at a GlobalEd opening event"}},{"photo":{"src":"/images/success/ielts-award.jpg","alt":"GlobalEd team receiving an award at a British Council IELTS event"}}]},"seo":{"title":"Our Success | GlobalEd","description":"GlobalEd''s track record — milestones since 2013, students placed, visa success rate, and real student success stories.","ogImage":"","ogImageAlt":""}}'::jsonb, 'Initial content', CURRENT_TIMESTAMP) ON CONFLICT ("key") DO NOTHING;
