INSERT INTO "SitePage" ("key", "published", "updatedByName", "updatedAt") VALUES ('contact', '{"hero":{"title":"Contact Us","description":"Walk into any of our branches, call us, or send a message — our counsellors are ready to help."},"form":{"title":"Send Us a Message","text":"Have a question about admissions, IELTS, or visas? Drop us a message and a counsellor will get back to you as soon as possible."},"seo":{"title":"Contact Us | GlobalEd","description":"Visit any GlobalEd branch in Panthapath, Uttara or Banasree — addresses, phone numbers, Google Maps, and our enquiry form.","ogImage":"","ogImageAlt":""}}'::jsonb, 'Initial content', CURRENT_TIMESTAMP) ON CONFLICT ("key") DO NOTHING;
