INSERT INTO "SitePage" ("key", "published", "updatedByName", "updatedAt") VALUES ('ielts', '{"hero":{"title":"IELTS with GlobalEd","description":"Whether your goal is to study abroad, migrate, advance your career, or improve your English proficiency, GlobalEd is committed to helping you achieve your target IELTS band score through expert guidance, personalized support, and real exam experience. From registration to test day, our team supports you at every step of your IELTS journey."},"cards":{"whatText":"Formats, modules, and scoring — the basics of the test.","whyText":"Why IELTS matters for study, work, and migration abroad.","withText":"British Council authorized testing, expert trainers, and free trial services.","preparationText":"A skill-by-skill program plus Essential, Advanced, and Premium packages.","bookTitle":"Book an IELTS Test","bookText":"Register for your official IELTS test or preparation package."},"stories":{"eyebrow":"Real Students. Real Results."},"seo":{"title":"IELTS with GlobalEd | GlobalEd","description":"What is IELTS, why it matters, why prepare with GlobalEd, our IELTS preparation packages, and IELTS test booking for students in Bangladesh.","ogImage":"","ogImageAlt":""}}'::jsonb, 'Initial content', CURRENT_TIMESTAMP) ON CONFLICT ("key") DO NOTHING;
